import numpy as np
from scipy.optimize import least_squares
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
L2=np.log(1+P)**2
F={'1':np.ones_like(t),'t':t,'t2':t**2,'sqrt t':np.sqrt(t),'exp(-t)':np.exp(-t),'log t':np.log(t),'1/t':1/t,'cos t':np.cos(t),'sin t':np.sin(t)}
H={'1':np.ones_like(P),'P':P,'P2':P**2,'sqrtP':np.sqrt(P),'1/P':1/P,'exp(-P)':np.exp(-P),'logP':np.log(1+P),'1/(1+P)':1/(1+P),'P/(1+P)':P/(1+P),'sinP':np.sin(P),'cosP':np.cos(P),'P(1-P/10)':P*(1-P/10),'exp(P)':np.exp(-P/3),'tanh P':np.tanh(P),'P^1.5':P**1.5}
out=[]
for fn,f in F.items():
  for hn,h in H.items():
    def model(p):
        k=p[0]
        A=np.c_[np.sin(k*P)*t, L2, f*h]
        c,_,_,_=np.linalg.lstsq(A,y,rcond=None)
        return y-A@c
    best=None
    for k0 in np.linspace(0.1,4,20):
        r=least_squares(model,[k0])
        v=np.mean(r.fun**2)/np.var(y)
        if best is None or v<best[0]: best=(v,r.x[0])
    out.append((best[0],best[1],fn,hn))
out.sort()
